  /** helper function to set the values of all input ports.
   * @param cargo_band payload for data port cargo_band
   * @param capacitor_band payload for data port capacitor_band
   * @param location payload for data port location
   * @param mining_available payload for data port mining_available
   * @param defense_available payload for data port defense_available
   * @param retreat_available payload for data port retreat_available
   * @param destination_available payload for data port destination_available
   * @param service_available payload for data port service_available
   */
  def put_concrete_inputs(cargo_band : Mining_Threat_Retreat_Supervision.CargoBandValue,
                          capacitor_band : Mining_Threat_Retreat_Supervision.CapacitorBandValue,
                          location : Mining_Threat_Retreat_Supervision.LocationValue,
                          mining_available : Mining_Threat_Retreat_Supervision.MiningAvailabilityValue,
                          defense_available : Mining_Threat_Retreat_Supervision.DefenseAvailabilityValue,
                          retreat_available : Mining_Threat_Retreat_Supervision.RetreatAvailabilityValue,
                          destination_available : Mining_Threat_Retreat_Supervision.DestinationAvailabilityValue,
                          service_available : Mining_Threat_Retreat_Supervision.ServiceAvailabilityValue): Unit = {
    put_cargo_band(cargo_band)
    put_capacitor_band(capacitor_band)
    put_location(location)
    put_mining_available(mining_available)
    put_defense_available(defense_available)
    put_retreat_available(retreat_available)
    put_destination_available(destination_available)
    put_service_available(service_available)
  }


  /** helper function to check Readiness_Assessment_supervisor_process_readiness_assessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param assessment_mining method that will be called with the value of the outgoing data
   *        port 'assessment_mining'.
   * @param assessment_defense method that will be called with the value of the outgoing data
   *        port 'assessment_defense'.
   * @param assessment_mobility method that will be called with the value of the outgoing data
   *        port 'assessment_mobility'.
   */
  def check_concrete_output(assessment_mining: Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue => B,
                            assessment_defense: Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue => B,
                            assessment_mobility: Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val assessment_miningValue: Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue = get_assessment_mining().get
    if(!assessment_mining(assessment_miningValue)) {
      testFailures = testFailures :+ st"'assessment_mining' did not match expected: value of the outgoing data port is ${assessment_miningValue}"
    }
    val assessment_defenseValue: Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue = get_assessment_defense().get
    if(!assessment_defense(assessment_defenseValue)) {
      testFailures = testFailures :+ st"'assessment_defense' did not match expected: value of the outgoing data port is ${assessment_defenseValue}"
    }
    val assessment_mobilityValue: Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue = get_assessment_mobility().get
    if(!assessment_mobility(assessment_mobilityValue)) {
      testFailures = testFailures :+ st"'assessment_mobility' did not match expected: value of the outgoing data port is ${assessment_mobilityValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


